Translate the following GNU C++ code to Java 8 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <cstdio>
#include <queue>
#include <cstring>
#include <algorithm>
#include <utility>
using namespace std;

typedef pair<int,int> pii;

const int MAXN = 300;
const int MAXE = 900000;

int n, t;
int S, T;
int rp, cp;
int in;

int levelArr[MAXN], head[MAXN], itArr[MAXN];
int edgeTo[MAXE], edgeNext[MAXE], edgeCap[MAXE], edgeCnt;

int srcId[21][21], sinkId[21][21];
int mark[21][21], dist[21][21];
char grid[21][21], grid2[21][21];

int dr[4] = {-1, 0, 1, 0};
int dc[4] = {0, 1, 0, -1};

void addEdge(int f, int t, int c) {
    edgeTo[edgeCnt] = t;
    edgeCap[edgeCnt] = c;
    edgeNext[edgeCnt] = head[f];
    head[f] = edgeCnt++;
    swap(f, t);
    edgeTo[edgeCnt] = t;
    edgeCap[edgeCnt] = 0;
    edgeNext[edgeCnt] = head[f];
    head[f] = edgeCnt++;
}

bool bfs(int source, int sink) {
    memset(levelArr, -1, sizeof(levelArr));
    queue<int> q;
    levelArr[source] = 0;
    q.push(source);
    while (!q.empty()) {
        int v = q.front(); q.pop();
        for (int e = head[v]; e != -1; e = edgeNext[e]) {
            if (edgeCap[e] > 0 && levelArr[edgeTo[e]] == -1) {
                levelArr[edgeTo[e]] = levelArr[v] + 1;
                q.push(edgeTo[e]);
            }
        }
    }
    return levelArr[sink] != -1;
}

int dfs(int v, int sink, int flow) {
    if (v == sink) return flow;
    for (int &e = itArr[v]; e != -1; e = edgeNext[e]) {
        if (edgeCap[e] > 0 && levelArr[v] + 1 == levelArr[edgeTo[e]]) {
            int pushed = dfs(edgeTo[e], sink, min(flow, edgeCap[e]));
            if (pushed) {
                edgeCap[e] -= pushed;
                edgeCap[e ^ 1] += pushed;
                return pushed;
            }
        }
    }
    return 0;
}

int maxflow(int source, int sink) {
    int ans = 0;
    while (bfs(source, sink)) {
        memcpy(itArr, head, sizeof(head));
        while (true) {
            int pushed = dfs(source, sink, 1 << 30);
            if (!pushed) break;
            ans += pushed;
        }
    }
    return ans;
}

bool valid(int r, int c) {
    return r >= 0 && r < n && c >= 0 && c < n;
}

void searchEdges(int a, int b) {
    queue<pii> q;
    memset(mark, 0, sizeof(mark));
    memset(dist, -1, sizeof(dist));
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (grid[i][j] == 'Y') mark[i][j] = 1;

    q.push(make_pair(rp, cp));
    q.push(make_pair(a, b));
    dist[a][b] = dist[rp][cp] = 0;
    mark[a][b] = 1;
    mark[rp][cp] = 2;

    while (!q.empty()) {
        pii now = q.front(); q.pop();
        int r = now.first, c2 = now.second;
        if (mark[r][c2] == 1 && grid2[r][c2] > '0' && grid2[r][c2] <= '9')
            addEdge(srcId[a][b], sinkId[r][c2], 9);

        if (mark[r][c2] == 1 && dist[r][c2] == t) continue;

        for (int k = 0; k < 4; ++k) {
            int nr = r + dr[k], nc = c2 + dc[k];
            if (valid(nr, nc) && mark[nr][nc] == 0) {
                mark[nr][nc] = mark[r][c2];
                dist[nr][nc] = dist[r][c2] + 1;
                q.push(make_pair(nr, nc));
            } else if (mark[r][c2] == 1 && valid(nr, nc) && mark[nr][nc] == 2 && dist[nr][nc] == dist[r][c2] + 1 && grid2[nr][nc] > '0' && grid2[nr][nc] <= '9') {
                addEdge(srcId[a][b], sinkId[nr][nc], 9);
            }
        }
    }
}

int main() {
    if (scanf("%d %d", &n, &t) != 2) return 0;
    S = 202; T = 203;
    memset(head, -1, sizeof(head));
    edgeCnt = 0;
    in = 0;
    memset(srcId, -1, sizeof(srcId));
    memset(sinkId, -1, sizeof(sinkId));

    for (int i = 0; i < n; ++i) {
        scanf("%s", grid[i]);
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] > '0' && grid[i][j] <= '9') {
                addEdge(S, in, grid[i][j] - '0');
                srcId[i][j] = in++;
            }
            if (grid[i][j] == 'Z') {
                rp = i; cp = j;
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        scanf("%s", grid2[i]);
        for (int j = 0; j < n; ++j) {
            if (grid2[i][j] > '0' && grid2[i][j] <= '9') {
                addEdge(in, T, grid2[i][j] - '0');
                sinkId[i][j] = in++;
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] > '0' && grid[i][j] <= '9' && grid2[i][j] > '0' && grid2[i][j] <= '9')
                addEdge(srcId[i][j], sinkId[i][j], 9);
            if (grid[i][j] > '0' && grid[i][j] <= '9')
                searchEdges(i, j);
        }
    }

    printf("%d\n", maxflow(S, T));
    return 0;
}
